`import React, { useState } from 'react';
import { ChevronRight, HelpCircle, ShieldCheck, Sparkles } from 'lucide-react';

const faqItems = [
  {
    id: 1,
    question: 'How do you approach the design of a new product?',
    answer: (
      <div className="space-y-2">
        <div className="flex items-start gap-3 text-stone-400">
          <div className="rounded-xl bg-white/10 p-3 text-indigo-400 shadow-lg shadow-indigo-500/20"><HelpCircle size={16} /></div>
          <p className="text-sm text-slate-300">In the initial discovery phase, I conduct user research and competitive analysis to define the problem space. I prioritize accessibility and inclusive design principles, ensuring the product meets the needs of all users.</p>
        </div>
      </div>
    ),
  },
  {
    id: 2,
    question: 'Do you work on design systems for enterprise clients?',
    answer: (
      <div className="space-y-2">
        <div className="flex items-start gap-3 text-stone-400">
          <div className="rounded-xl bg-white/10 p-3 text-emerald-400 shadow-lg shadow-emerald-500/20"><ShieldCheck size={16} /></div>
          <p className="text-sm text-slate-300">Absolutely! I've built comprehensive design systems for enterprise clients, focusing on scalability, maintainability, and brand consistency. We work together to define the component library and style guide that align with the company's visual identity.</p>
        </div>
      </div>
    ),
  },
  {
    id: 3,
    question: 'How do you handle tight deadlines without compromising quality?',
    answer: (
      <div className="space-y-2">
        <div className="flex items-start gap-3 text-stone-400">
          <div className="rounded-xl bg-white/10 p-3 text-amber-400 shadow-lg shadow-amber-500/20"><ChevronRight size={16} /></div>
          <p className="text-sm text-slate-300">I prioritize time management by breaking down the scope into actionable sprints. Regular check-ins with stakeholders ensure alignment and feedback are incorporated efficiently. Clear documentation and version control processes help streamline the handoff phases.</p>
        </div>
      </div>
    ),
  },
  {
    id: 4,
    question: 'Can you share a recent project you worked on?',
    answer: (
      <div className="space-y-2">
        <div className="flex items-start gap-3 text-stone-400">
          <div className="rounded-xl bg-white/10 p-3 text-blue-400 shadow-lg shadow-blue-500/20"><Sparkles size={16} /></div>
          <p className="text-sm text-slate-300">For a global e-commerce platform, I led the redesign of the checkout flow and cart interface. The project involved optimizing form fields for faster checkout rates, implementing real-time pricing updates, and enhancing the mobile shopping experience with optimized layouts and micro-interactions.</p>
        </div>
      </div>
    ),
  },
];

export default function Faq() {
  const [isOpen, setIsOpen] = useState(0);
  const [isHovered, setIsHovered] = useState(0);

  const toggleAccordion = (id) => {
    if (isOpen === id) {
      setIsOpen(0);
    } else {
      setIsOpen(id);
    }
  };

  const handleHover = (id) => {
    setIsHovered(id);
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-8 bg-slate-950 text-slate-100">
      <div className="mb-12 text-center">
        <h2 className="text-2xl sm:text-3xl font-bold text-slate-100 tracking-tight mb-2">
          Frequently Asked Questions
        </h2>
        <p className="text-slate-400 text-sm sm:text-base max-w-lg mx-auto mb-8">
          Here are some common questions about my process and approach as a product designer.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {faqItems.map((item) => {
          const isExpanded = isOpen === item.id;
          const isHoveredItem = isHovered === item.id;
          const borderColor = isHoveredItem || isExpanded ? 'border-indigo-500/30' : 'border-white/10';

          return (
            <div
              key={item.id}
              onMouseEnter={() => handleHover(item.id)}
              onMouseLeave={() => handleHover(0)}
              className="relative overflow-hidden rounded-2xl border bg-slate-900/90 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02]"
            >
              <div className="absolute -top-2 -right-2 -z-10 w-12 h-12 rounded-xl bg-white/10 border border-white/20 pointer-events-none" />
              <div className="relative z-10">
                <div className="flex items-center justify-between pb-4 border-b border-white/10">
                  <div className="flex items-center space-x-2">
                    <div className="rounded-xl p-2 text-indigo-400 bg-indigo-500/10"><ChevronRight size={14} className="w-5 h-5" /></div>
                    <h3 className="text-sm font-semibold text-slate-200 flex-1">{item.question}</h3>
                  </div>
                  <div className="flex items-center space-x-1 text-sm text-slate-400">
                    <div className="rounded-xl bg-white/5 p-2 text-indigo-400 hover:text-indigo-300 transition-colors duration-200"><ChevronRight size={14} /></div>
                  </div>
                </div>
                {isExpanded || isHoveredItem ? (
                  <div className="p-8">
                    {item.answer}
                  </div>
                ) : (
                  <div className="p-4">
                    <p className="text-slate-400 text-sm">{item.answer}</p>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Mail, Sparkles, CheckCircle2, Briefcase, Camera, ArrowUpRight, Filter, Search, X, Plus } from 'lucide-react';

const projects = [
  {
    id: 1,
    title: 'Omnichannel Retail Ecosystem',
    role: 'System Design Lead',
    category: 'E-commerce',
    stack: 'Figma, Zeplin, Miro',
    summary: 'Transformed a legacy B2B storefront into a seamless, multi-channel shopping experience.',
    impact: '+25% customer engagement, -10% cart abandonment',
    stackBadge: 'Figma',
    imageUrl: 'https://images.unsplash.com/photo-1522071820081-009f3b6b01b1?w=800&q=80',
    overlayGradient: 'from-rose-500/20 via-amber-500/10 to-transparent',
    date: 'Mar 2023 - Present'
  },
  {
    id: 2,
    title: 'Enterprise Identity System',
    role: 'UX Art Director',
    category: 'Brand & Identity',
    stack: 'Illustration Kit, Color Palette',
    summary: 'Redefined a global enterprise’s visual identity for a 15% brand lift.',
    impact: '+15% brand affinity, +40K followers on social',
    stackBadge: 'Illustration',
    imageUrl: 'https://images.unsplash.com/photo-1496122811754-6c922371b65f?w=800&q=80',
    overlayGradient: 'from-purple-500/20 via-blue-500/10 to-transparent',
    date: 'Sep 2022 - Dec 2023'
  },
  {
    id: 3,
    title: 'Growth Engine Platform',
    role: 'Visual Studio Lead',
    category: 'Subscription & Billing',
    stack: 'Trello, Slack',
    summary: 'Streamlined the onboarding flow for a subscription-based SaaS, reducing churn by 12%.',
    impact: '-12% churn rate, +25K monthly active users',
    stackBadge: 'Trello',
    imageUrl: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=800&q=80',
    overlayGradient: 'from-cyan-500/20 via-teal-500/10 to-transparent',
    date: 'Apr 2022 - Jul 2023'
  }
];

export default function Work() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('All');
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [selectedProject, setSelectedProject] = useState(null);

  const filteredProjects = projects.filter(item => {
    const titleMatch = item.title.toLowerCase().includes(searchTerm.toLowerCase());
    const categoryMatch = filterCategory === 'All' || item.category.toLowerCase() === filterCategory.toLowerCase();
    return titleMatch && categoryMatch;
  });

  const handleSelect = (project) => {
    setSelectedProject(project);
    setIsAddOpen(true);
  };

  const handleClose = () => {
    setSelectedProject(null);
    setIsAddOpen(false);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans antialiased">
      {/* Decorative Gradient Header Bar */}
      <div className="h-48 bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 bg-blend-multiply p-4 shadow-2xl">
        <div className="container mx-auto flex items-center justify-between px-6">
          <div>
            <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-white via-slate-300 to-transparent">
              Work
            </h1>
            <p className="text-slate-400 text-sm mt-1">Selected projects from the past year</p>
          </div>
          <button
            onClick={() => setIsAddOpen(true)}
            className="p-2 bg-white/10 text-slate-300 border border-white/10 rounded-lg hover:bg-white/20 transition-all duration-300 shadow-lg shadow-indigo-500/10"
          >
            <Plus className="w-5 h-5 text-white" />
          </button>
        </div>
      </div>

      {/* Main Work Section */}
      <div className="container mx-auto px-6 pb-24">
        <div className="mb-16 flex flex-col items-center justify-center text-center">
          <div className="w-full max-w-sm text-center rounded-3xl bg-white/5 p-4 backdrop-blur-xl border border-white/10 shadow-2xl shadow-indigo-500/10">
            <div className="mb-6 flex items-center justify-center">
              <Filter className="w-6 h-6 text-indigo-400" />
              <span className="ml-3 text-sm tracking-wide text-slate-400">Filter & Search</span>
            </div>
            <div className="relative mb-8">
              <Search className="absolute left-3 top-1.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Search projects..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-lg py-2 pl-10 pr-4 text-slate-400 placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all duration-200"
              />
            </div>
            <div className="mb-10 flex flex-wrap gap-4">
              {['All', 'E-commerce', 'Identity', 'Subscription'].map((cat) => (
                <button
                  key={cat}
                  onClick={() => setFilterCategory(cat)}
                  className={`py-2 px-3 rounded-xl border transition-colors duration-200 ${
                    cat === filterCategory ? 'border-indigo-500 bg-indigo-500/10 text-indigo-400' : 'border-white/10 text-slate-400 hover:text-slate-100 hover:border-white/20'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
            <div className="space-y-4">
              {filteredProjects.map((p) => (
                <div
                  key={p.id}
                  className="relative group rounded-2xl border border-white/10 bg-white/5 backdrop-blur-xl p-6 transition-all duration-300 hover:border-white/20 hover:shadow-lg hover:scale-[1.01] hover:shadow-indigo-500/10"
                >
                  <div className="absolute -inset-0.5 bg-white/5 backdrop-blur-md rounded-2xl" />
                  <div className="relative flex flex-col overflow-hidden rounded-2xl bg-white/10 p-6 backdrop-blur-xl border border-white/10 hover:border-white/20 transition-all duration-300 hover:shadow-lg hover:shadow-indigo-500/10">
                    <div className="relative mb-6 flex flex-col items-start gap-2">
                      <h2 className="text-lg font-semibold tracking-wide text-slate-100">{p.title}</h2>
                      <p className="text-xs text-slate-400">{p.date}</p>
                    </div>
                    <div className="mb-6 flex items-start justify-between gap-3">
                      <div className="flex flex-col gap-1">
                        <span className="text-xs text-slate-400">{p.category}</span>
                        <span className="text-xs font-semibold text-slate-300">{p.role}</span>
                      </div>
                      <div className="flex items-center gap-1">
                        <span className="text-xs text-slate-400">{p.stackBadge}</span>
                        <Sparkles className="w-3.5 h-3.5 text-violet-400" />
                      </div>
                    </div>
                    <div className="relative">
                      <div className="absolute -inset-0.5 bg-white/5 backdrop-blur-md rounded-xl" />
                      <p className="text-sm text-slate-400">{p.summary}</p>
                    </div>
                    <div className="mt-6 flex flex-col gap-3">
                      <button
                        onClick={() => handleSelect(p)}
                        className="inline-flex justify-center gap-2 rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-slate-200 hover:bg-white/10 border border-white/10 hover:border-white/20 transition-all duration-200 active:scale-95 hover:shadow-lg hover:shadow-indigo-500/10"
                      >
                        <ArrowUpRight className="w-4 h-4 text-slate-300" /> Explore
                      </button>
                      {selectedProject && (
                        <button
                          onClick={handleClose}
                          className="inline-flex justify-center gap-2 rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-slate-200 hover:bg-white/10 border border-white/10 hover:border-white/20 transition-all duration-200 active:scale-95 hover:shadow-lg hover:shadow-indigo-500/10"
                        >
                          <X className="w-4 h-4 text-slate-300" /> Close
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
